import{_ as a,o as e,c as d,a5 as i}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"家庭学习篇：把成长还给孩子","description":"为大致处于初中阶段的学习者、家长与教师建立一套共同学习方法，用孩子的目标表达、短任务、作品证据、家庭边界和安全的 AI 使用替代监控与代做。","frontmatter":{"title":"家庭学习篇：把成长还给孩子","description":"为大致处于初中阶段的学习者、家长与教师建立一套共同学习方法，用孩子的目标表达、短任务、作品证据、家庭边界和安全的 AI 使用替代监控与代做。","updated":"2026-09-02T00:00:00.000Z","sources_checked":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-4/family-learning.md","filePath":"threads/part-4/family-learning.md","lastUpdated":1788307200000}'),l={name:"threads/part-4/family-learning.md"};function r(s,t,n,h,p,o){return e(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="家庭学习篇-把成长还给孩子" tabindex="-1">家庭学习篇：把成长还给孩子 <a class="header-anchor" href="#家庭学习篇-把成长还给孩子" aria-label="Permalink to &quot;家庭学习篇：把成长还给孩子&quot;">​</a></h1><p>一个孩子坐在书桌前，家长站在门口，双方都觉得自己在为同一件事努力。</p><p>家长问：“今天背了多少？错题改完了吗？为什么又在看别的？”孩子回答得越来越短。桌上有计划表、打卡软件、练习册和 AI 生成的学习方案，任务似乎比过去更清楚，家里的空气却越来越紧。</p><p>问题不一定是谁不够负责。很多家庭真正缺少的，是一套能够同时容纳学校要求、孩子的成长、家长的担心和现实容量的方法。成人版本的“自主管理”不能直接套给尚未拥有完整时间、账户和决策权的学习者；成人也不能因此接管目标、答案和每一分钟。</p><p>这一章面向大致处于初中阶段的学习者及其家长、监护人和教师。它不承诺提高名次，不替代学校教学，也不是心理、医疗或家庭教育诊断。它只试图建立一张共同桌面：孩子可以说出自己想学什么、哪里不会、今天能承担多少；成人负责安全、资源和边界；老师提供课程要求与专业反馈；AI 只能在被允许的位置参与。</p><p>成长需要帮助，但帮助不应把成长的主人挤出房间。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>先确认这是谁的问题、谁的目标，以及学校有哪些不能忽略的要求；</li><li>用一份短小、未经代做的样本建立起点，不用成绩总排名定义孩子；</li><li>家长负责环境、安全、资源和沟通，不负责代答、持续监控或公开展示；</li><li>每周只推进一个真实任务，让输入、输出、反馈、延迟复测和迁移进入同一条证据链；</li><li>AI 使用服从平台年龄规则、学校要求和家庭约定，儿童数据默认不进入通用模型；</li><li>当睡眠、安全、持续痛苦、校园伤害或家庭冲突成为主要问题时，先暂停学习实验并寻求合适支持。</li></ul><h2 id="_1-先问-这是谁想要的改变" tabindex="-1">1. 先问：这是谁想要的改变 <a class="header-anchor" href="#_1-先问-这是谁想要的改变" aria-label="Permalink to &quot;1. 先问：这是谁想要的改变&quot;">​</a></h2><p>“把英语学好”“提高成绩”“不要沉迷手机”常常由成人提出。它们可能出于真实关心，却还不是孩子能够执行的问题。</p><p>第一次谈话不急着制定计划。请让三方分别回答：</p><table tabindex="0"><thead><tr><th>角色</th><th>需要说清的问题</th></tr></thead><tbody><tr><td>学习者</td><td>我最近在哪个真实场景卡住？我希望哪件事变得容易一点？什么帮助让我不舒服？</td></tr><tr><td>家长/监护人</td><td>我真正担心的是成绩、安全、睡眠、习惯、未来，还是失去控制？哪些担心有事实，哪些只是想象？</td></tr><tr><td>教师/学校</td><td>当前课程、作业、考试与课堂有哪些明确要求？哪些能力可以用作品或表现观察？</td></tr></tbody></table><p>三方答案不必完全相同。家庭需要的不是迅速统一口径，而是把冲突从人格判断改写成可以讨论的条件。</p><p>例如：</p><ul><li>成人目标：“词汇量必须提高。”</li><li>学习者问题：“英语阅读时一遇到生词就停下来，最后不知道文章在说什么。”</li><li>学校要求：“本月需要完成两篇相近难度的阅读与一次课堂复述。”</li><li>共同问题：“我能否在不逐词查字典的情况下读完一篇短文，写出主旨，并在七天后用另一篇文章再做一次？”</li></ul><p>共同问题既保留学校现实，也给孩子留下可以理解和回答的动作。它不要求孩子先认同成人对未来的全部判断。</p><h2 id="_2-不用总分替代起点" tabindex="-1">2. 不用总分替代起点 <a class="header-anchor" href="#_2-不用总分替代起点" aria-label="Permalink to &quot;2. 不用总分替代起点&quot;">​</a></h2><p>成绩能说明某次评价中发生了什么，却不能独自解释问题来自词汇、理解、表达、时间、焦虑、睡眠、课堂缺席还是任务不清。一次家庭学习实验需要更小的基线。</p><p>先选择一个 10–20 分钟、不会公开羞辱孩子的任务：</p><ul><li>阅读一篇符合当前课程难度的短文，用三句话复述；</li><li>听一段一到两分钟的材料，写下主旨和两个细节；</li><li>不看答案完成三道同类型题，并说明为什么这样做；</li><li>用英语介绍一项兴趣，允许停顿，但要回答一个真实追问；</li><li>写一段代码、做一个科学解释，或把当天错题按原因分成三类。</li></ul><p>保存原始版本，不当场连续纠正十个问题。先问四件事：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这个任务原本要求什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">孩子独立完成了什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">在哪里停住或开始猜：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次只值得改变哪个条件：</span></span></code></pre></div><p>基线属于学习者，不应被发到家庭群、社交平台或用来与同学比较。成人需要知道足够的信息来提供支持，不等于拥有公开孩子所有表现的权利。</p><h2 id="_3-四个角色-不互相代替" tabindex="-1">3. 四个角色，不互相代替 <a class="header-anchor" href="#_3-四个角色-不互相代替" aria-label="Permalink to &quot;3. 四个角色，不互相代替&quot;">​</a></h2><p>一个可靠的家庭学习系统，需要明确谁对什么负责：</p><table tabindex="0"><thead><tr><th>角色</th><th>主要责任</th><th>不应该承担的角色</th></tr></thead><tbody><tr><td>学习者</td><td>提交自己的首版；说明困难、容量和需要；参与选择下一任务</td><td>为成人的焦虑提供持续证明</td></tr><tr><td>家长/监护人</td><td>保护时间、睡眠、安全、设备和必要资源；帮助沟通；执行隐私边界</td><td>代写答案、全天监控、用羞耻维持计划</td></tr><tr><td>教师/学校</td><td>说明课程要求；提供与学科相关的反馈和支持路径</td><td>被 AI 或家庭臆测取代</td></tr><tr><td>AI/工具</td><td>在允许范围内解释、提问、生成平行练习和整理错误</td><td>充当监护人、决定孩子价值、代做提交作品或保存儿童隐私</td></tr></tbody></table><p>孩子拥有参与权，不等于独自承担所有责任。成人拥有保护责任，也不等于拥有每一个答案。角色清楚以后，帮助才不必通过接管发生。</p><h2 id="_4-家长的工作-是搭环境而不是站在背后" tabindex="-1">4. 家长的工作，是搭环境而不是站在背后 <a class="header-anchor" href="#_4-家长的工作-是搭环境而不是站在背后" aria-label="Permalink to &quot;4. 家长的工作，是搭环境而不是站在背后&quot;">​</a></h2><p>持续监督会制造一种表面效率：孩子在被看见时行动，成人一离开，系统便失去动力。更稳妥的家庭支持包含四类工作。</p><h3 id="保护一个可用时间盒" tabindex="-1">保护一个可用时间盒 <a class="header-anchor" href="#保护一个可用时间盒" aria-label="Permalink to &quot;保护一个可用时间盒&quot;">​</a></h3><p>不是要求每天固定两小时，而是和孩子确认一段现实可用、能够结束的时间。初次实验可以是 20–35 分钟：开始前知道任务，结束时保存版本，不因未完成继续拖到深夜。</p><h3 id="减少启动摩擦" tabindex="-1">减少启动摩擦 <a class="header-anchor" href="#减少启动摩擦" aria-label="Permalink to &quot;减少启动摩擦&quot;">​</a></h3><p>把材料、账号、耳机、字典、纸笔或文件提前准备好。成人可以帮忙找到学校指定资源、处理设备故障和安排空间，却不需要坐在旁边盯住每一个动作。</p><h3 id="只问能改变下一步的问题" tabindex="-1">只问能改变下一步的问题 <a class="header-anchor" href="#只问能改变下一步的问题" aria-label="Permalink to &quot;只问能改变下一步的问题&quot;">​</a></h3><p>比“今天认真了吗”更有用的是：</p><ul><li>哪一步你能独立完成？</li><li>哪一步需要提示？</li><li>这个提示是帮你理解，还是直接给了答案？</li><li>明天打开文件后，第一步是什么？</li></ul><h3 id="保护结束" tabindex="-1">保护结束 <a class="header-anchor" href="#保护结束" aria-label="Permalink to &quot;保护结束&quot;">​</a></h3><p>学习时间结束时，帮助孩子保存证据、写下下一入口，然后允许任务离开餐桌和卧室。没有结束边界的学习，会把整个家庭变成永远没有下课的教室。</p><h2 id="_5-一周只完成一个真实任务" tabindex="-1">5. 一周只完成一个真实任务 <a class="header-anchor" href="#_5-一周只完成一个真实任务" aria-label="Permalink to &quot;5. 一周只完成一个真实任务&quot;">​</a></h2><p>下面是一条适合家庭共同试验的七天路径，不要求每天满格：</p><table tabindex="0"><thead><tr><th>天数</th><th>学习者动作</th><th>成人支持</th><th>留下的证据</th></tr></thead><tbody><tr><td>第 1 天</td><td>完成未经代做的起点样本</td><td>说明时间和隐私边界</td><td>原始版本与一个困难</td></tr><tr><td>第 2 天</td><td>处理一个最影响结果的问题</td><td>提供指定材料或联系教师</td><td>来源与一句理解</td></tr><tr><td>第 3 天</td><td>合上材料完成第二版</td><td>不在过程中连续纠错</td><td>第二版</td></tr><tr><td>第 4 天</td><td>接受最多三条具体反馈</td><td>帮助区分观察、评价和建议</td><td>反馈原话与选择</td></tr><tr><td>第 5 天</td><td>只改一个变量</td><td>保护时间盒，不追加任务</td><td>修订版</td></tr><tr><td>第 6 天</td><td>不看旧答案做延迟复测</td><td>不提醒原答案</td><td>延迟样本</td></tr><tr><td>第 7 天</td><td>换主题、听众或题型做一次迁移</td><td>共同回顾，允许缩小或停止</td><td>新条件结果与下周决定</td></tr></tbody></table><p>如果学校作业已经足够多，家庭实验应嵌入现有任务，而不是再加一套课程。把同一份作业改造成可比较样本，通常比额外购买材料更可靠。</p><h2 id="_6-一个合成示例-用英语介绍自己的兴趣" tabindex="-1">6. 一个合成示例：用英语介绍自己的兴趣 <a class="header-anchor" href="#_6-一个合成示例-用英语介绍自己的兴趣" aria-label="Permalink to &quot;6. 一个合成示例：用英语介绍自己的兴趣&quot;">​</a></h2><p>下面是方法演示，不是真实学生个案，也不能代表所有初中生。</p><p>共同问题是：<strong>学习者能否不用逐句背稿，用英语介绍一项兴趣两分钟，并回答同学的一个追问？</strong></p><p>第一天的基线可能留下这些事实：</p><table tabindex="0"><thead><tr><th>条件</th><th>结果</th></tr></thead><tbody><tr><td>10 分钟准备，不用 AI</td><td>能说 45 秒；重复 <code>I like</code>；遇到追问后停止</td></tr><tr><td>学习者自己的判断</td><td>不是完全没词，而是不知道怎样组织原因和例子</td></tr><tr><td>成人担心</td><td>担心课堂不敢开口，但不把口音相似度当成目标</td></tr><tr><td>学校条件</td><td>下周有一次小组展示，可以作为真实听众场景</td></tr></tbody></table><p>这一周只保留三个结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I became interested in ... when ...</span></span>
<span class="line"><span>What I enjoy most is ... because ...</span></span>
<span class="line"><span>One thing I am still trying to learn is ...</span></span></code></pre></div><p>AI 或教师可以在学习者提交首版后，最多指出三个影响理解的问题，并生成一个不同兴趣主题的平行练习。最终课堂内容、事实与表达由学习者确认。</p><p>第六天不看原稿重录，第七天把听众换成家人或同学。若仍然只能背诵原句，下一周不增加更长词表，而是继续练习“原因—例子—仍在学习”的结构。</p><p>这项练习没有承诺提高考试名次。它只把词汇、组织、听众反馈和延迟复测放进同一个真实任务。</p><h2 id="_7-ai-进入家庭前-先过五道门" tabindex="-1">7. AI 进入家庭前，先过五道门 <a class="header-anchor" href="#_7-ai-进入家庭前-先过五道门" aria-label="Permalink to &quot;7. AI 进入家庭前，先过五道门&quot;">​</a></h2><p>UNESCO 的生成式 AI 教育指导强调人本视角和发展人的能力。对未成年学习者而言，“人本”不能只是漂亮口号，它至少要变成五项检查。</p><h3 id="年龄与账户门" tabindex="-1">年龄与账户门 <a class="header-anchor" href="#年龄与账户门" aria-label="Permalink to &quot;年龄与账户门&quot;">​</a></h3><p>先核对平台当前的年龄、账户、监护和地区规则，再核对学校要求。不要为了使用某项功能虚报年龄、借用陌生账户或绕过学校政策。规则会变化，家庭应以当前条款和学校通知为准。</p><h3 id="数据门" tabindex="-1">数据门 <a class="header-anchor" href="#数据门" aria-label="Permalink to &quot;数据门&quot;">​</a></h3><p>默认不上传姓名、学校、班级、证件、精确位置、面部、声纹、健康、家庭关系、成绩单、教师或同学的私人信息。练习可以使用合成姓名、改写材料和不可识别的最小片段。</p><h3 id="首版门" tabindex="-1">首版门 <a class="header-anchor" href="#首版门" aria-label="Permalink to &quot;首版门&quot;">​</a></h3><p>只要任务允许，孩子先提交自己的版本，再让 AI 提问、解释或反馈。若 AI 从第一步就给出完整作文、代码或答案，家庭获得的是成品，不是起点证据。</p><h3 id="判断门" tabindex="-1">判断门 <a class="header-anchor" href="#判断门" aria-label="Permalink to &quot;判断门&quot;">​</a></h3><p>AI 不决定孩子是否聪明、是否适合某个方向、朋友是否可信、身体是否有病，或家庭冲突中谁“就是有问题”。涉及安全、健康、校园伤害和持续痛苦时，回到可信成人、学校和当地合格专业支持。</p><h3 id="退出门" tabindex="-1">退出门 <a class="header-anchor" href="#退出门" aria-label="Permalink to &quot;退出门&quot;">​</a></h3><p>学习结束时保存作品、关闭会话，并让孩子能用自己的话复述。AI 不应成为唯一倾诉对象、全天陪伴者或家庭监督工具。工具退出之后仍能继续思考，才是能力留在人身上的证据。</p><h2 id="_8-三种容量-不用熬夜偿还学习" tabindex="-1">8. 三种容量，不用熬夜偿还学习 <a class="header-anchor" href="#_8-三种容量-不用熬夜偿还学习" aria-label="Permalink to &quot;8. 三种容量，不用熬夜偿还学习&quot;">​</a></h2><p>家庭可以共同写三个版本：</p><table tabindex="0"><thead><tr><th>档位</th><th>当天情况</th><th>学习动作</th><th>成人动作</th></tr></thead><tbody><tr><td>完整日</td><td>作业和身体状态相对稳定</td><td>20–35 分钟输入、输出和记录</td><td>保护时间，不临时加码</td></tr><tr><td>压缩日</td><td>作业变多、活动或通勤占用</td><td>10 分钟最小输出</td><td>帮助确定第一步和结束点</td></tr><tr><td>恢复日</td><td>生病、明显缺觉、受伤、冲突或容量很低</td><td>暂停训练，只保留下次入口</td><td>优先照料、安全、沟通和必要求助</td></tr></tbody></table><p>错过的训练不要求在周末一次补完，更不能用失去睡眠偿还。家庭若把“计划完整”放在身体和关系之前，计划本身就已经失去教育意义。</p><h2 id="_9-反馈不等于评判孩子" tabindex="-1">9. 反馈不等于评判孩子 <a class="header-anchor" href="#_9-反馈不等于评判孩子" aria-label="Permalink to &quot;9. 反馈不等于评判孩子&quot;">​</a></h2><p>反馈应该指向作品和条件，而不是人格：</p><table tabindex="0"><thead><tr><th>不够清楚的说法</th><th>更可执行的反馈</th></tr></thead><tbody><tr><td>你就是不认真</td><td>这次第三题没有写步骤，我不知道你从哪里开始猜</td></tr><tr><td>你英语基础太差</td><td>这段主旨能复述，但两个因果连接没有说清</td></tr><tr><td>AI 都讲过了怎么还不会</td><td>看过解释后能完成原题，七天后平行题仍需要提示</td></tr><tr><td>别人都能坚持</td><td>这周三次任务有两次在晚上太晚开始，我们需要换时间</td></tr></tbody></table><p>家长每次最多保留一个主问题和三条反馈。孩子也可以拒绝某条评价，并说明依据。共同学习不是取消成人判断，而是让判断能够被听见、核对和修正。</p><h2 id="_10-什么时候应该暂停学习实验" tabindex="-1">10. 什么时候应该暂停学习实验 <a class="header-anchor" href="#_10-什么时候应该暂停学习实验" aria-label="Permalink to &quot;10. 什么时候应该暂停学习实验&quot;">​</a></h2><p>出现下面情况时，不要先升级打卡、惩罚或 AI 监督：</p><ul><li>睡眠、饮食或身体不适持续影响日常功能；</li><li>学习前后反复出现强烈恐惧、绝望、失控或伤害念头；</li><li>存在校园暴力、欺凌、威胁、勒索、性骚扰或其他安全风险；</li><li>家庭冲突已经无法安全讨论，学习计划成为攻击或控制工具；</li><li>孩子长期拒绝进入学校或任务，且原因无法仅由一次沟通解释。</li></ul><p>先保证安全，联系可信成人、学校相关人员，并根据情况寻求当地合格的医疗、心理、社会服务或紧急支持。本章不能诊断原因，也不能替代专业处置。</p><p>暂停学习实验，不等于放弃成长。一个人需要先有可以站立的地面，方法才有地方发生。</p><h2 id="_11-用十四天决定继续、调整还是停止" tabindex="-1">11. 用十四天决定继续、调整还是停止 <a class="header-anchor" href="#_11-用十四天决定继续、调整还是停止" aria-label="Permalink to &quot;11. 用十四天决定继续、调整还是停止&quot;">​</a></h2><p>家庭不需要一开始承诺坚持一个学期。先用<a href="./../../templates/family-learning-agreement">家庭学习共同协议</a>完成十四天实验，并在结束时分别回答：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">学习者：哪一项能力或任务真的变容易了？什么帮助让我更愿意开始？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">家长：我提供了什么环境支持？哪一种监督没有带来价值？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">共同证据：有哪些首版、反馈、延迟复测或真实使用结果？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">学校信息：教师要求或课堂表现给出了什么新事实？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一决定：继续 / 缩小 / 改变一个条件 / 暂停或停止</span></span></code></pre></div><p>不要在孩子面前召开一场只有成人发言的“复盘会”。学习者先说，成人再补充；事实冲突时保留两种记录，必要时向教师确认。</p><h2 id="_12-给家庭的一份最小约定" tabindex="-1">12. 给家庭的一份最小约定 <a class="header-anchor" href="#_12-给家庭的一份最小约定" aria-label="Permalink to &quot;12. 给家庭的一份最小约定&quot;">​</a></h2><p>如果今天只能开始四行，可以写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">孩子这两周想完成的一件真实事情：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">家长只提供的两项支持：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">绝不上传或公开的信息：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">两周后用什么作品和对话决定下一步：</span></span></code></pre></div><p>这四行不是法律合同，也不保证冲突消失。它只是把“都是为你好”改写成双方能够复查的责任。</p><h2 id="来源与边界" tabindex="-1">来源与边界 <a class="header-anchor" href="#来源与边界" aria-label="Permalink to &quot;来源与边界&quot;">​</a></h2><ul><li><a href="https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research" target="_blank" rel="noreferrer">UNESCO：Guidance for generative AI in education and research</a>，2026-09-02 核验；本章只采用其人本与能力发展方向，不把国际指导替代为本地学校规则、平台条款或专业意见。</li><li>具体平台年龄、账户、监护与数据规则可能变化，使用前应核对当前官方条款、学校政策与当地适用要求。</li></ul><p>相关入口：<a href="./week-1">实践篇：先把第一周过完</a> ｜ <a href="./daily-system">生活系统篇</a> ｜ <a href="./../../templates/family-learning-agreement">家庭学习共同协议</a></p><h2 id="结语-不要替孩子走完那条路" tabindex="-1">结语：不要替孩子走完那条路 <a class="header-anchor" href="#结语-不要替孩子走完那条路" aria-label="Permalink to &quot;结语：不要替孩子走完那条路&quot;">​</a></h2><p>家长比孩子看见更多风险，也常常更早看见时间的重量。正因为如此，爱很容易变成代走：替他选目标，替他解释失败，替他保管每一分钟，再替他证明这一切都是必要的。</p><p>可学习最珍贵的部分，恰恰不能由别人完成。一个孩子需要亲自遇见不会，亲自做出不够好的第一版，亲自听见反馈，也亲自发现七天以后留下些什么。成人可以守住灯、门和回家的路，却不能替他长出判断。</p><p>愿家庭里的学习，不再是一场谁更焦虑谁就更有权发言的比赛。愿孩子能够说“这是我想完成的”，也能够说“今天我做不到”；愿成人听见这两句话之后，仍然知道怎样帮助，而不急着夺走方向。</p><p>成长不是把孩子送往一个由成人预先画好的终点。它是陪他在越来越大的世界里，逐渐拥有自己的脚步。</p>`,93)])])}const u=a(l,[["render",r]]);export{b as __pageData,u as default};
